struct HeavyResource {};

// 1. Unique Ownership (std::unique_ptr)
std::unique_ptr<HeavyResource> u1 =
    std::make_unique<HeavyResource>();

// u2 takes over ownership (Move)
std::unique_ptr<HeavyResource> u2 = std::move(u1);
// u1 is now nullptr

u2.reset(); // Explicitly release resource

// 2. Shared Ownership (std::shared_ptr)
std::shared_ptr<int> s1 = std::make_shared<int>(42);
std::shared_ptr<int> s2 = s1; // Copy (Ref count: 2)

if (s1.use_count() == 2) { /* true */ }

// 3. Weak Reference (std::weak_ptr)
std::weak_ptr<int> w = s1; // Does not increment count

if (auto locked = w.lock()) {
    // Access resource safely
}
s1.reset(); // Resource deleted
if (w.expired()) { /* true */ }
